use vstd::prelude::*;

verus! {
    fn split_and_append(list: &Vec<i32>, n: usize) -> (new_list: Vec<i32>)
        requires
            list.len() > 0,
            0 < n && n < list.len(),
        ensures
            new_list.len() == list.len(),
            new_list == list[n..].to_vec() + list[0..n].to_vec(),
    {
        let len = list.len();
        let mut new_list: Vec<i32> = Vec::new();
        let mut i: usize = 0;

        // First, append the subarray from index n to the end
        while i < len - n
            invariant
                0 <= i <= len - n,
                new_list.len() == i,
                new_list == list[n..(n + i)].to_vec(),
            decreases len - n - i,
        {
            new_list.push(list[n + i]);
            i = i + 1;
        }

        // Now, append the subarray from index 0 to n-1
        let mut j: usize = 0;
        while j < n
            invariant
                0 <= j <= n,
                new_list.len() == (len - n) + j,
                new_list == list[n..].to_vec() + list[0..j].to_vec(),
            decreases n - j,
        {
            new_list.push(list[j]);
            j = j + 1;
        }

        new_list
    }
}
